function lc_admin_translate_html(string $html, string $locale): string
{
    $map = lc_admin_dictionary()[$locale] ?? lc_admin_dictionary()['en'];
    uksort($map, static fn(string $a, string $b): int => strlen($b) <=> strlen($a));
    return str_replace(array_keys($map), array_values($map), $html);
}
